function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 300000) return 'nums needs 1 to 300000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 100)) return 'Each value is an integer from 1 to 100.';
  const prime = (v) => { if (v < 2) return false; for (let d = 2; d * d <= v; d++) if (v % d === 0) return false; return true; };
  if (!nums.some(prime)) return 'nums must contain at least one prime number.';
  return null;
}

