function maximumPrimeDifference(nums) {
  const prime = (v) => {
    if (v < 2) return false;
    for (let d = 2; d < v; d++) if (v % d === 0) return false;
    return true;
  };
  let best = 0;
  for (let i = 0; i < nums.length; i++)
    for (let j = i; j < nums.length; j++)
      if (prime(nums[i]) && prime(nums[j])) best = Math.max(best, j - i);
  return best;
}

